export default class AnimationData {
    alpha: number = 1

    scale: number = 1

    init: number = 1

    initDuration: number = 0

    initDelay: number = 0

    initStart: DOMHighResTimeStamp | null = null

    /**
     * Item is removed, init animation is played backward and item is dropped from queue at the end
     */
    isLeaving: boolean = false

    /**
     * Progress (0..1) of moving from previous geometry to current one
     */
    morph: number = 1

    morphDuration: number = 0

    morphStart: DOMHighResTimeStamp | null = null

    /**
     * Opacity follows morph progress: 'in' when item appears from placeholder, 'out' when it becomes placeholder
     */
    morphFade: 'in' | 'out' | null = null

    /**
     * Item is dropped from queue when morph is finished
     */
    removeAfterMorph: boolean = false

    /**
     * Opacity follows init progress, used for items appeared or removed on rebuild
     */
    initFade: boolean = false

    /**
     * Opacity (0..1) of show/hide animations, multiplied with alpha
     */
    visibility: number = 1

    get isInitializing() {
        return this.initDuration > 0
    }

    get isMorphing() {
        return this.morphDuration > 0
    }

    static get default() {
        return new AnimationData()
    }
}